export function getDirectorRecipesByCategory(category: DirectorRecipeCategory): DirectorRecipe[] {
  return directorRecipeCatalog.filter((recipe) => recipe.category === category);
}

export function getDirectorRecipesBySection(section: StartExtendedSectionId): DirectorRecipe[] {
  return directorRecipeCatalog.filter((recipe) => recipe.recommendedStaRtSections.includes(section));
}

export function getDirectorRecipeById(id: string): DirectorRecipe | undefined {
  return directorRecipeCatalog.find((recipe) => recipe.id === id);
}

export function buildPalmierRecipeHandoff(recipe: DirectorRecipe): string {
  return [
    `Director recipe: ${recipe.id} / ${recipe.label}`,
    `Category: ${recipe.category} / ${recipe.subCategory}`,
    `Purpose: ${recipe.purpose}`,
    `Camera: ${recipe.cameraGrammar}`,
    `Edit: ${recipe.editGrammar}`,
    `Typography: ${recipe.typographyGrammar}`,
    `Transition: ${recipe.transitionGrammar}`,
    `Beat: ${recipe.beatBehavior} / Energy: ${recipe.energy.join(", ")} / Density: ${recipe.density.join(", ")}`,
    `Duration: ${recipe.durationFrames[0]}-${recipe.durationFrames[1]} frames @30fps`,
    `Source type: ${recipe.sourceType}`,
    `Motion Kit presets: ${recipe.motionPresetIds.join(", ")}`,
    `Recommended StaRt sections: ${recipe.recommendedStaRtSections.join(", ")}`,
    `Avoid when: ${recipe.avoidWhen}`,
    `AI-template risk: ${recipe.aiTemplateRisk}`,
    `Over-editing risk: ${recipe.overEditingRisk}`,
    "Keep real bride/groom/family/friends/dog imagery unchanged. Do not generate or transform identity.",
    "This is a planned recipe. Do not auto-approve; record the artifact for human review.",
  ].join("\n");
}
